class Account {
  static count = 0;
  #balance = 0;                   // private field
  owner;                          // public field, own property

  constructor(owner) {
    this.owner = owner;
    Account.count++;
  }
  deposit(amount) {               // on Account.prototype
    if (amount <= 0) throw new RangeError("amount must be positive");
    this.#balance += amount;
    return this;
  }
  get balance() { return this.#balance; }
  static isAccount(x) { return #balance in x; }
}

